function validate([lights]) {
  if (!Array.isArray(lights) || lights.length < 1 || lights.length > 100000) return 'lights needs 1 to 100000 lamps.';
  for (const lamp of lights) {
    if (!Array.isArray(lamp) || lamp.length !== 2) return 'Each lamp is a pair [position, range].';
    const [position, range] = lamp;
    if (!Number.isInteger(position) || position < -100000000 || position > 100000000) return 'Each position is an integer from -10^8 to 10^8.';
    if (!Number.isInteger(range) || range < 0 || range > 100000000) return 'Each range is an integer from 0 to 10^8.';
  }
  return null;
}

