function brightestPosition(lights) {
  const change = new Map();
  for (const [position, range] of lights) {
    const start = position - range;
    const end = position + range + 1;
    change.set(start, (change.get(start) ?? 0) + 1);
    change.set(end, (change.get(end) ?? 0) - 1);
  }

  const points = [...change.keys()].sort((a, b) => a - b);
  let brightness = 0;
  let best = 0;
  let answer = points[0];
  for (const point of points) {
    brightness += change.get(point);
    if (brightness > best) {
      best = brightness;
      answer = point;
    }
  }
  return answer;
}

