function brightestPosition(lights) {
  // Brightness only rises where some lamp's lit area begins, so the smallest brightest
  // position is the left end of some lamp's area: try each one and count directly.
  let bestCount = -1;
  let bestPosition = 0;
  for (const [p, r] of lights) {
    const x = p - r;
    let lit = 0;
    for (const [q, s] of lights) if (q - s <= x && x <= q + s) lit++;
    if (lit > bestCount || (lit === bestCount && x < bestPosition)) {
      bestCount = lit;
      bestPosition = x;
    }
  }
  return bestPosition;
}

