function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  const mode = int(0, 2);
  // Small streets make overlaps and ties common; the widest mode uses the full limits.
  const spread = size === 'small' ? [10, 30, 3][mode] : [100000000, 5000, 100][mode];
  const reach = size === 'small' ? [5, 3, 2][mode] : [100000000, 2000, 50][mode];
  const lights = [];
  for (let i = 0; i < n; i++) lights.push([int(-spread, spread), int(0, reach)]);
  return [lights];
}
